<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 12px;
    background: #f2ecfa;
    font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
    display: flex;
    justify-content: center;
  }
  .page {
    width: 560px;
    background: #fff;
    border: 3px solid #b9a3e0;
    border-radius: 16px;
    padding: 14px 12px 20px 12px;
  }
  .title {
    text-align: center;
    font-size: 30px;
    font-weight: 900;
    color: #6b4fa0;
    letter-spacing: 2px;
    margin: 4px 0 14px 0;
    text-shadow: 1px 1px 0 #d9c8f0;
  }
  .grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px 10px;
  }
  .card {
    border: 2px solid #b9a3e0;
    border-radius: 10px;
    overflow: hidden;
    background: #fff;
    display: flex;
    flex-direction: column;
  }
  .card-header {
    background: linear-gradient(135deg, #b79ce0, #c9b3ea);
    color: #fff;
    text-align: center;
    font-size: 16px;
    font-weight: bold;
    padding: 6px 0;
    letter-spacing: 1px;
  }
  .row {
    display: flex;
    align-items: flex-start;
    padding: 4px 8px;
    font-size: 12.5px;
    line-height: 1.4;
  }
  .row:not(:last-child) {
    border-bottom: 1px dashed #e0d5f2;
  }
  .label {
    flex: 0 0 34px;
    color: #8a6fc0;
    font-weight: bold;
    white-space: nowrap;
  }
  .content {
    flex: 1;
    color: #333;
  }
</style>
</head>
<body>
<div class="page">
  <div class="title">宝宝腹泻怎么办</div>
  <div class="grid">

    <!-- 病毒性腹泻 -->
    <div class="card">
      <div class="card-header">病毒性腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">轮状病毒引起秋冬季多发</span></div>
      <div class="row"><span class="label">症状</span><span class="content">呕吐发烧，上呼吸道感染</span></div>
      <div class="row"><span class="label">大便</span><span class="content">大便呈水样</span></div>
      <div class="row"><span class="label">护理</span><span class="content">辅食清淡易消化</span></div>
    </div>

    <!-- 过敏性腹泻 -->
    <div class="card">
      <div class="card-header">过敏性腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">食物中的蛋白质过敏</span></div>
      <div class="row"><span class="label">症状</span><span class="content">湿疹、荨麻疹、哮喘</span></div>
      <div class="row"><span class="label">大便</span><span class="content">大便增多，无明显水样便</span></div>
      <div class="row"><span class="label">护理</span><span class="content">辅食避开过敏原，换深度水解奶粉</span></div>
    </div>

    <!-- 喂养不当腹泻 -->
    <div class="card">
      <div class="card-header">喂养不当腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">辅食添加过早如杂致消化不良</span></div>
      <div class="row"><span class="label">症状</span><span class="content">呕吐，哭闹</span></div>
      <div class="row"><span class="label">大便</span><span class="content">有泡沫，混有颗粒物/黏液</span></div>
      <div class="row"><span class="label">护理</span><span class="content">暂停或减少辅食，清淡饮食，少量多次治疗</span></div>
    </div>

    <!-- 细菌性腹泻 -->
    <div class="card">
      <div class="card-header">细菌性腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">病原微生物引起在夏季高发</span></div>
      <div class="row"><span class="label">症状</span><span class="content">腹痛恶心，发热，没食欲</span></div>
      <div class="row"><span class="label">大便</span><span class="content">大便稀且有黏液，严重时便血</span></div>
      <div class="row"><span class="label">护理</span><span class="content">补液避免脱水，注意饮食卫生</span></div>
    </div>

    <!-- 乳糖不耐受腹泻 -->
    <div class="card">
      <div class="card-header">乳糖不耐受腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">由于肠道中缺乏乳糖酶引起</span></div>
      <div class="row"><span class="label">症状</span><span class="content">肠胀气、肠绞痛，吃奶就拉</span></div>
      <div class="row"><span class="label">大便</span><span class="content">次数多，大便有奶瓣泡沫状</span></div>
      <div class="row"><span class="label">护理</span><span class="content">母乳妈妈忌口高糖和奶制品</span></div>
    </div>

    <!-- 受凉引起腹泻 -->
    <div class="card">
      <div class="card-header">受凉引起腹泻</div>
      <div class="row"><span class="label">原因</span><span class="content">由腹部或身体受凉引起</span></div>
      <div class="row"><span class="label">症状</span><span class="content">胃胀，恶心，呕吐，屁多</span></div>
      <div class="row"><span class="label">大便</span><span class="content">大便水样，有泡沫</span></div>
      <div class="row"><span class="label">护理</span><span class="content">注意身体和肚子保暖，不吃生冷辛辣</span></div>
    </div>

  </div>
</div>
</body>
</html>
